begin;
create schema if not exists workforce_recognition_private;
revoke all on schema workforce_recognition_private from public, anon, authenticated;
create table public.workforce_recognition_roles (
 role_key text primary key, label text not null, family text not null, definition jsonb not null
);
create table public.workforce_progression_levels (
 level int primary key check(level between 1 and 5), label text not null,
 credits int not null, contexts int not null, employers int not null
);
insert into public.workforce_progression_levels values
 (1,'Qualified',1,1,1),(2,'Experienced',5,3,1),(3,'Advanced',15,8,2),
 (4,'Veteran',30,15,3),(5,'Expert',60,25,4);
create table public.workforce_role_credits (
 id uuid primary key default gen_random_uuid(),
 assignment_id uuid not null unique references public.employment_assignments(id) on delete restrict,
 user_id uuid not null references auth.users(id) on delete restrict,
 role_key text not null references public.workforce_recognition_roles(role_key), family text not null,
 event_id uuid references public.events(id) on delete restrict,
 canonical_event_id uuid references public.events_v2(id) on delete restrict,
 tour_id uuid references public.tours(id) on delete restrict,
 staff_member_id uuid not null references public.staff_members(id) on delete restrict,
 staff_shift_id uuid references public.staff_shifts(id) on delete restrict,
 context_key text not null, employer_entity_type text not null, employer_entity_id uuid not null,
 verified_by uuid not null references auth.users(id) on delete restrict,
 verified_at timestamptz not null default now(), completed_at timestamptz not null,
 endorsement text not null check(length(endorsement) between 10 and 2000),
 evidence text not null check(length(evidence) between 10 and 2000),
 endorsement_expires_at timestamptz not null default (now()+interval '24 months'),
 assignment_snapshot jsonb not null, role_snapshot jsonb not null, context_snapshot jsonb not null,
 revoked_at timestamptz, revoked_by uuid references auth.users(id), revocation_reason text,
 check(user_id<>verified_by), check(event_id is not null or tour_id is not null),
 check((revoked_at is null and revoked_by is null and revocation_reason is null) or
  (revoked_at is not null and revoked_by is not null and length(revocation_reason)>=10)),
 unique(user_id,role_key,context_key)
);
create index workforce_credit_user on public.workforce_role_credits(user_id);
create index workforce_credit_employer on public.workforce_role_credits(employer_entity_type,employer_entity_id);
create table public.workforce_advancement_history (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id),
 badge_key text not null, previous_level int not null, new_level int not null,
 credit_id uuid not null references public.workforce_role_credits(id), actor_id uuid not null references auth.users(id),
 occurred_at timestamptz not null default now(), reason text not null, model_version int not null default 1
);
create index workforce_history_user on public.workforce_advancement_history(user_id,occurred_at);
create table public.workforce_recognition_visibility (
 user_id uuid primary key references auth.users(id), is_public boolean not null default false
);
alter table public.workforce_recognition_roles enable row level security;
alter table public.workforce_progression_levels enable row level security;
alter table public.workforce_role_credits enable row level security;
alter table public.workforce_advancement_history enable row level security;
alter table public.workforce_recognition_visibility enable row level security;
revoke all on public.workforce_recognition_roles,public.workforce_progression_levels,
 public.workforce_role_credits,public.workforce_advancement_history,public.workforce_recognition_visibility
 from public,anon,authenticated;
grant select on public.workforce_recognition_roles,public.workforce_progression_levels,
 public.workforce_role_credits,public.workforce_advancement_history to authenticated;
create policy workforce_roles_read on public.workforce_recognition_roles for select to authenticated using(true);
create policy workforce_levels_read on public.workforce_progression_levels for select to authenticated using(true);
-- Existing service workflows need to inspect the immutable-assignment guard.
grant select on public.workforce_role_credits to service_role;
create policy workforce_credits_read on public.workforce_role_credits for select to authenticated
 using(user_id=(select auth.uid()) or public.can_manage_hiring(auth.uid(),employer_entity_type,employer_entity_id));
create policy workforce_history_read on public.workforce_advancement_history for select to authenticated
 using(user_id=(select auth.uid()));
grant select,insert,update on public.workforce_recognition_visibility to authenticated;
create policy workforce_visibility_own on public.workforce_recognition_visibility for all to authenticated
 using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));

create function workforce_recognition_private.badges(p_user uuid) returns jsonb
language sql stable set search_path='' as $$
 with counts as (
 select 'role:'||c.role_key badge_key,r.label,count(*)::int credits,count(distinct c.context_key)::int contexts,
 count(distinct c.employer_entity_type||':'||c.employer_entity_id)::int employers
 from public.workforce_role_credits c join public.workforce_recognition_roles r using(role_key)
 where c.user_id=p_user and c.revoked_at is null group by c.role_key,r.label
 union all
 select 'family:'||family,initcap(replace(family,'_',' ')),count(distinct context_key)::int,
 count(distinct context_key)::int,count(distinct employer_entity_type||':'||employer_entity_id)::int
 from public.workforce_role_credits where user_id=p_user and revoked_at is null group by family
 )
 select coalesce(jsonb_agg(jsonb_build_object('badge_key',badge_key,'label',c.label,'credits',c.credits,
 'contexts',c.contexts,'employers',c.employers,'level',coalesce(l.level,0),'level_label',coalesce(l.label,'Uncredited'),
 'next_level',(select to_jsonb(n) from public.workforce_progression_levels n where n.level=coalesce(l.level,0)+1),
 'model_version',1) order by badge_key),'[]'::jsonb)
 from counts c left join lateral(select level,label from public.workforce_progression_levels l
 where c.credits>=l.credits and c.contexts>=l.contexts and c.employers>=l.employers order by level desc limit 1) l on true;
$$;
create function workforce_recognition_private.record_advancement(p_user uuid,p_before jsonb,p_credit uuid,p_actor uuid,p_reason text)
returns void language plpgsql set search_path='' as $$
declare b record;
begin
 for b in with old as(select value->>'badge_key' k,(value->>'level')::int l from jsonb_array_elements(p_before)),
 new as(select value->>'badge_key' k,(value->>'level')::int l from jsonb_array_elements(workforce_recognition_private.badges(p_user)))
 select coalesce(old.k,new.k) k,coalesce(old.l,0) prev,coalesce(new.l,0) next from old full join new using(k)
 where coalesce(old.l,0)<>coalesce(new.l,0)
 loop
 insert into public.workforce_advancement_history(user_id,badge_key,previous_level,new_level,credit_id,actor_id,reason)
 values(p_user,b.k,b.prev,b.next,p_credit,p_actor,p_reason);
 end loop;
end;
$$;
create function workforce_recognition_private.verify(p_assignment uuid,p_endorsement text,p_evidence text)
returns uuid language plpgsql security definer set search_path='' as $$
declare a public.employment_assignments; s public.staff_members; r public.workforce_recognition_roles;
 actor uuid:=auth.uid(); v_id uuid; v_before jsonb; v_context text; context_data jsonb; v_event uuid; v_tour uuid; shift_data jsonb;
begin
 if actor is null then raise exception 'Authentication required' using errcode='42501'; end if;
 select * into a from public.employment_assignments where id=p_assignment for update;
 if not found then raise exception 'Assignment not found' using errcode='P0002'; end if;
 if actor=a.user_id or not coalesce(public.can_manage_hiring(actor,a.employer_entity_type,a.employer_entity_id),false) then
 raise exception 'Only an authorized employer/manager may verify another worker' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(a.user_id::text,0));
 if p_endorsement is null or p_evidence is null or length(trim(p_endorsement)) not between 10 and 2000
 or length(trim(p_evidence)) not between 10 and 2000 then
 raise exception 'Endorsement and evidence must be 10–2000 characters' using errcode='22023'; end if;
 select id into v_id from public.workforce_role_credits where assignment_id=a.id;
 if found then return v_id; end if;
 if a.status='confirmed' and a.staff_shift_id is not null then
 select to_jsonb(sh) into shift_data from public.staff_shifts sh where id=a.staff_shift_id;
 end if;
 if (a.status not in ('active','completed') and not(coalesce(shift_data->>'status','')='completed'
 and shift_data->>'staff_member_id'=a.staff_member_id::text)) or a.starts_at is null or a.ends_at is null
 or a.starts_at>=a.ends_at or a.ends_at>now() then
 raise exception 'Assignment must have been active and its work window must have ended' using errcode='22023'; end if;
 select * into s from public.staff_members where id=a.staff_member_id;
 if not found or s.user_id is distinct from a.user_id or s.employer_entity_type is distinct from a.employer_entity_type
 or s.employer_entity_id is distinct from a.employer_entity_id or coalesce(s.status,'') not in ('active','inactive') then
 raise exception 'Matching hired workforce record required' using errcode='22023'; end if;
 select * into r from public.workforce_recognition_roles where role_key=a.role_key;
 if not found then raise exception 'Map this assignment to a catalog role before verification' using errcode='22023'; end if;
 v_tour:=a.tour_id;
 if a.event_id is not null then
 -- Employment assignments still reference legacy events. Resolve the explicit
 -- producer bridge to events_v2; never infer identity from title/date.
 select coalesce(nullif(to_jsonb(e)->>'promoted_event_v2_id','')::uuid,e.id) into v_event
 from public.events e where id=a.event_id;
 select to_jsonb(e) into context_data from public.events_v2 e where id=v_event;
 if context_data is null or context_data->>'status' is distinct from 'settled'
 or nullif(context_data->>'end_at','') is null or (context_data->>'end_at')::timestamptz>now() then
 raise exception 'Canonical event must be settled and ended (archived/cancelled is not completion)' using errcode='22023'; end if;
 if not coalesce((coalesce(context_data->>'created_by','')=actor::text
 or public.has_entity_permission(actor,'Event',v_event,'ASSIGN_EVENT_ROLES')
 or (a.employer_entity_type='organization' and context_data->>'org_id'=a.employer_entity_id::text)
 or (a.employer_entity_type='venue' and context_data->>'venue_id'=a.employer_entity_id::text)),false) then
 raise exception 'Employer must be authorized for the event context' using errcode='42501'; end if;
 if (select count(*) from public.tour_events where event_id=v_event)>1 then
 raise exception 'Event has ambiguous tour membership; resolve before credit' using errcode='22023'; end if;
 select tour_id into v_tour from public.tour_events where event_id=v_event;
 if a.tour_id is not null and a.tour_id is distinct from v_tour then
 raise exception 'Assignment tour does not match the canonical event' using errcode='22023'; end if;
 v_context:='event:'||v_event;
 elsif a.tour_id is not null then
 select to_jsonb(t) into context_data from public.tours t where id=a.tour_id;
 if context_data is null or context_data->>'status' is distinct from 'completed'
 or nullif(context_data->>'end_date','') is null or (context_data->>'end_date')::date>=current_date then
 raise exception 'Tour must be completed and its final date must have passed' using errcode='22023'; end if;
 if not coalesce((coalesce(context_data->>'created_by','')=actor::text
 or public.has_entity_permission(actor,'Tour',a.tour_id,'ASSIGN_EVENT_ROLES')
 or (a.employer_entity_type='organization' and context_data->>'org_id'=a.employer_entity_id::text)),false) then
 raise exception 'Employer must be authorized for the tour context' using errcode='42501'; end if;
 v_context:='tour:'||a.tour_id;
 else raise exception 'An event or tour is required' using errcode='22023'; end if;
 -- Prevent tour-wide credit from overlapping ANY role in the same family,
 -- including event assignments that omit tour_id but have canonical membership.
 if v_tour is not null and exists(select 1 from public.workforce_role_credits c
 where c.user_id=a.user_id and c.family=r.family and c.tour_id=v_tour
 and (c.canonical_event_id is null or v_event is null)) then
 raise exception 'Tour-wide and stop-level family credit overlap' using errcode='23505'; end if;
 v_before:=workforce_recognition_private.badges(a.user_id);
 insert into public.workforce_role_credits(assignment_id,user_id,role_key,family,event_id,canonical_event_id,tour_id,staff_member_id,
 staff_shift_id,context_key,employer_entity_type,employer_entity_id,verified_by,completed_at,endorsement,evidence,
 assignment_snapshot,role_snapshot,context_snapshot)
 values(a.id,a.user_id,r.role_key,r.family,a.event_id,v_event,v_tour,a.staff_member_id,a.staff_shift_id,v_context,
 a.employer_entity_type,a.employer_entity_id,actor,a.ends_at,trim(p_endorsement),trim(p_evidence),to_jsonb(a),
 jsonb_build_object('catalog',r.definition,'hired_definition',a.role_definition_snapshot),context_data) returning id into v_id;
 update public.employment_assignments set status='completed' where id=a.id;
 perform workforce_recognition_private.record_advancement(a.user_id,v_before,v_id,actor,'Verified assignment completion');
 return v_id;
end;
$$;
create function workforce_recognition_private.revoke(p_credit uuid,p_reason text)
returns void language plpgsql security definer set search_path='' as $$
declare c public.workforce_role_credits; v_before jsonb; actor uuid:=auth.uid();
begin
 select * into c from public.workforce_role_credits where id=p_credit;
 if not found then raise exception 'Credit not found' using errcode='P0002'; end if;
 if actor is null or actor=c.user_id or not coalesce(public.can_manage_hiring(actor,c.employer_entity_type,c.employer_entity_id),false) then
 raise exception 'Employer/manager permission required' using errcode='42501'; end if;
 if p_reason is null or length(trim(p_reason)) not between 10 and 2000 then
 raise exception 'Revocation reason must be 10–2000 characters' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(c.user_id::text,0));
 select * into c from public.workforce_role_credits where id=p_credit for update;
 if c.revoked_at is not null then return; end if;
 v_before:=workforce_recognition_private.badges(c.user_id);
 update public.workforce_role_credits set revoked_at=now(),revoked_by=actor,revocation_reason=trim(p_reason) where id=c.id;
 perform workforce_recognition_private.record_advancement(c.user_id,v_before,c.id,actor,trim(p_reason));
end;
$$;
create function workforce_recognition_private.profile(p_user uuid) returns jsonb
language plpgsql security definer stable set search_path='' as $$
declare own boolean:=auth.uid()=p_user;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if not coalesce(own,false) and not exists(select 1 from public.workforce_recognition_visibility where user_id=p_user and is_public) then
 return jsonb_build_object('badges','[]'::jsonb,'endorsements','[]'::jsonb,'history','[]'::jsonb,'is_public',false); end if;
 return jsonb_build_object('badges',workforce_recognition_private.badges(p_user),
 'is_public',coalesce((select is_public from public.workforce_recognition_visibility where user_id=p_user),false),
 'endorsements',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'role_key',c.role_key,'role_label',r.label,
 'endorsement',c.endorsement,'verified_at',c.verified_at,'expires_at',c.endorsement_expires_at,
 'verification','Employer/manager verified')) from public.workforce_role_credits c join public.workforce_recognition_roles r using(role_key)
 where c.user_id=p_user and c.revoked_at is null and c.endorsement_expires_at>now()),'[]'::jsonb),
 'history',coalesce((select jsonb_agg(jsonb_build_object('badge_key',h.badge_key,'previous_level',h.previous_level,
 'new_level',h.new_level,'occurred_at',h.occurred_at,'reason',case when own then h.reason else 'Verified work progression' end)
 order by h.occurred_at desc) from public.workforce_advancement_history h where user_id=p_user),'[]'::jsonb));
end;
$$;
create function public.verify_workforce_assignment(p_assignment uuid,p_endorsement text,p_evidence text)
returns uuid language sql security invoker set search_path='' as $$
 select workforce_recognition_private.verify(p_assignment,p_endorsement,p_evidence); $$;
create function public.revoke_workforce_credit(p_credit uuid,p_reason text)
returns void language sql security invoker set search_path='' as $$
 select workforce_recognition_private.revoke(p_credit,p_reason); $$;
create function public.workforce_recognition_profile(p_user uuid) returns jsonb
language sql security invoker stable set search_path='' as $$select workforce_recognition_private.profile(p_user);$$;
revoke all on all functions in schema workforce_recognition_private from public,anon,authenticated;
grant usage on schema workforce_recognition_private to authenticated;
grant execute on function workforce_recognition_private.verify(uuid,text,text),
 workforce_recognition_private.revoke(uuid,text),workforce_recognition_private.profile(uuid) to authenticated;
revoke all on function public.verify_workforce_assignment(uuid,text,text),public.revoke_workforce_credit(uuid,text),
 public.workforce_recognition_profile(uuid) from public,anon;
grant execute on function public.verify_workforce_assignment(uuid,text,text),public.revoke_workforce_credit(uuid,text),
 public.workforce_recognition_profile(uuid) to authenticated;
create function workforce_recognition_private.protect_assignment() returns trigger
language plpgsql set search_path='' as $$
begin
 if auth.uid() is not null and auth.uid()=old.user_id
 and not coalesce(public.can_manage_hiring(auth.uid(),old.employer_entity_type,old.employer_entity_id),false) then
 if(to_jsonb(new)-array['status','updated_at']) is distinct from(to_jsonb(old)-array['status','updated_at'])
 or not(new.status=old.status or(old.status='invited' and new.status in('confirmed','cancelled'))) then
 raise exception 'Workers may only accept or decline invitations' using errcode='42501'; end if; end if;
 if exists(select 1 from public.workforce_role_credits where assignment_id=old.id) then
 if (to_jsonb(new)-array['status','updated_at']) is distinct from (to_jsonb(old)-array['status','updated_at'])
 or not(new.status=old.status or(old.status in('active','confirmed') and new.status='completed')) then
 raise exception 'Verified assignments cannot be reused or rewritten; create a new assignment for new work' using errcode='22023';
 end if; end if;
 return new;
end;
$$;
revoke all on function workforce_recognition_private.protect_assignment() from public,anon,authenticated;
create trigger workforce_protect_assignment before update on public.employment_assignments
 for each row execute function workforce_recognition_private.protect_assignment();
insert into public.workforce_recognition_roles(role_key,label,family,definition) values
('ada-accessibility-team','ADA Accessibility Team','hospitality','{"key":"ada-accessibility-team","label":"ADA Accessibility Team","department":"Guest Services","role_category":"hospitality","employment_type":"part_time","job_summary":"Coordinates accessibility services so guests with disabilities can navigate and participate in the event.","duties":["Support accessible entry, seating, viewing, transportation, and service requests","Coordinate accommodations with guest services, security, medical, and site operations","Document accessibility issues and escalate unresolved barriers"],"qualifications":["Guest services, accessibility, disability-services, or event-operations experience preferred","Respectful communication, discretion, and problem-solving skills"],"required_credentials":[{"key":"accessibility-training","label":"Accessibility / disability inclusion training","isRequired":false,"isExpiryTracked":false}],"essentials":["Know the event accessibility plan and escalation contacts","Protect guest privacy and dignity","Maintain reliable communications while assigned"],"workflow_requirements":{"management_surfaces":["workforce","communications","guest_services","site_operations","scheduling","incident_reporting"],"lifecycle":["plan","staff","schedule","onboard","execute","handoff","closeout"],"requires_shift_assignment":true,"requires_check_in":true,"handoff_required":true,"incident_reporting":true},"tags":["guest-services","hospitality","accessibility","ada"]}'::jsonb),
('artist-hospitality','Artist Hospitality','hospitality','{"key":"artist-hospitality","label":"Artist Hospitality","department":"Artist Services","role_category":"hospitality","employment_type":"contractor","job_summary":"Supports artists and touring parties with dressing rooms, hospitality, meals, arrivals, and day-of needs.","duties":["Prepare and maintain artist hospitality areas","Coordinate hospitality-rider needs with catering and production","Track artist arrivals, requests, and department handoffs"],"qualifications":["Live-event, hospitality, or artist-services experience preferred","Professional discretion and calm guest-facing communication"],"required_credentials":[],"essentials":["Current artist schedule and hospitality rider access","Clear escalation path to artist relations or production","Confidential handling of artist information"],"workflow_requirements":{"management_surfaces":["workforce","communications","advancing","catering","scheduling","tasks"],"lifecycle":["plan","staff","schedule","onboard","execute","handoff","closeout"],"requires_shift_assignment":true,"requires_check_in":true,"handoff_required":true,"incident_reporting":false},"tags":["artist-services","hospitality"]}'::jsonb),
('artist-relations-manager','Artist Relations Manager','management','{"key":"artist-relations-manager","label":"Artist Relations Manager","department":"Artist Services","role_category":"management","employment_type":"contractor","job_summary":"Owns the day-of relationship between the event and artists, managers, and touring teams.","duties":["Serve as primary artist-facing contact","Coordinate arrivals, credentials, hospitality, schedule changes, and issue resolution","Maintain handoffs with production, talent buying, security, and transportation"],"qualifications":["Several years of artist-relations, touring, venue, or festival-operations experience","Strong conflict-resolution, scheduling, and stakeholder-management skills"],"required_credentials":[],"essentials":["Access to artist contacts, schedules, riders, and escalation tree","Authority to coordinate cross-department resolutions","Accurate confidential handoffs"],"workflow_requirements":{"management_surfaces":["workforce","communications","advancing","credentials","scheduling","transportation","tasks"],"lifecycle":["plan","staff","schedule","onboard","execute","handoff","closeout"],"requires_shift_assignment":true,"requires_check_in":true,"handoff_required":true,"incident_reporting":false},"tags":["artist-services","management","artist-relations"]}'::jsonb),
('audio-engineer','Audio Engineer','technical','{"key":"audio-engineer","label":"Audio Engineer","department":"Production","role_category":"technical","employment_type":"contractor","job_summary":"Operates and supports live-audio systems to deliver safe, intelligible, artist-appropriate sound.","duties":["Prepare and operate assigned audio systems","Coordinate line checks, sound checks, and show cues with stage and artist teams","Report equipment, signal, or safety issues to production leadership"],"qualifications":["Professional live-sound experience appropriate to the system and show scale","Working knowledge of signal flow, consoles, RF/audio coordination, and safe production practices"],"required_credentials":[{"key":"audio-safety","label":"Live audio / electrical safety training","isRequired":false,"isExpiryTracked":false}],"essentials":["Approved system and show-file access where applicable","Required PPE and hearing protection","Clear cueing and communications path"],"workflow_requirements":{"management_surfaces":["workforce","communications","run_of_show","equipment","scheduling","incident_reporting"],"lifecycle":["plan","staff","schedule","onboard","execute","handoff","closeout"],"requires_shift_assignment":true,"requires_check_in":true,"handoff_required":true,"incident_reporting":true},"tags":["production","technical","audio","sound"]}'::jsonb),
